<?php
require_once __DIR__ . '/../includes/auth.php';
require_login();

// The dashboard, reports, budgets, and allowance calculations use the unified
// transactions ledger. Route legacy expense links there to prevent new records
// from being saved in the disconnected expenses table below.
flash('Use Transactions to record expenses so your dashboard and reports stay up to date.', 'info');
redirect('transactions/index.php?type=Expense');

$page_title='Expenses'; require_once __DIR__ . '/../includes/header.php'; $errors=[];$editing=null;$cats=categories();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';$id=(int)($_POST['id']??0);if($action==='delete'){if(ownership('expenses',$id)){db()->prepare('DELETE FROM expenses WHERE id=? AND user_id=?')->execute([$id,user_id()]);flash('Expense deleted successfully.');}else flash('Expense not found.','danger');header('Location: /expenses/index.php');exit;}$category=(int)($_POST['category_id']??0);$value=amount($_POST['amount']??'');$date=$_POST['expense_date']??'';$desc=trim($_POST['description']??'');$validCat=ownership('categories',$category);if(!$validCat)$errors[]='Please select one of your categories.';if($value===null)$errors[]='Please enter a valid amount.';if(!valid_date($date))$errors[]='Please enter a valid date.';if(!$errors){if($action==='update'&&ownership('expenses',$id)){db()->prepare('UPDATE expenses SET category_id=?,amount=?,expense_date=?,description=? WHERE id=? AND user_id=?')->execute([$category,$value,$date,$desc,$id,user_id()]);flash('Expense updated successfully.');}else{db()->prepare('INSERT INTO expenses (user_id,category_id,amount,expense_date,description) VALUES (?,?,?,?,?)')->execute([user_id(),$category,$value,$date,$desc]);flash('Expense added successfully.');}header('Location: /expenses/index.php');exit;}$editing=['id'=>$id,'category_id'=>$category,'amount'=>$_POST['amount'],'expense_date'=>$date,'description'=>$desc];}
if(isset($_GET['edit']))$editing=ownership('expenses',(int)$_GET['edit']);$search=trim($_GET['search']??'');$catFilter=(int)($_GET['category_id']??0);$from=$_GET['from']??'';$to=$_GET['to']??'';$where=['e.user_id=?'];$args=[user_id()];if($search!==''){$where[]='e.description LIKE ?';$args[]="%$search%";}if($catFilter&&ownership('categories',$catFilter)){$where[]='e.category_id=?';$args[]=$catFilter;}if(valid_date($from)){$where[]='e.expense_date>=?';$args[]=$from;}if(valid_date($to)){$where[]='e.expense_date<=?';$args[]=$to;}$q=db()->prepare('SELECT e.*,c.name category_name FROM expenses e JOIN categories c ON c.id=e.category_id WHERE '.implode(' AND ',$where).' ORDER BY e.expense_date DESC,e.id DESC');$q->execute($args);$rows=$q->fetchAll();?><div class="d-flex justify-content-between align-items-center mb-4"><h1 class="page-title">Expenses</h1><button class="btn btn-primary" data-bs-toggle="collapse" data-bs-target="#expenseForm">+ Add Expense</button></div><?php foreach($errors as $x):?><div class="alert alert-danger"><?=e($x)?></div><?php endforeach;?><div class="collapse <?=$editing?'show':''?> mb-4" id="expenseForm"><div class="card p-4"><h5><?=$editing?'Edit expense':'Add expense'?></h5><form method="post" class="row g-3"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="<?=$editing?'update':'create'?>"><input type="hidden" name="id" value="<?=e($editing['id']??'')?>"><div class="col-md-3"><label class="form-label">Category</label><select class="form-select" name="category_id" required><option value="">Select category</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=((int)($editing['category_id']??0)===$c['id'])?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></div><div class="col-md-2"><label class="form-label">Amount (RM)</label><input class="form-control" name="amount" type="number" min="0.01" step="0.01" required value="<?=e($editing['amount']??'')?>"></div><div class="col-md-3"><label class="form-label">Date</label><input class="form-control" name="expense_date" type="date" required value="<?=e($editing['expense_date']??date('Y-m-d'))?>"></div><div class="col-md-4"><label class="form-label">Description</label><input class="form-control" name="description" value="<?=e($editing['description']??'')?>"></div><div><button class="btn btn-primary"><?=$editing?'Update Expense':'Save Expense'?></button><?php if($editing):?><a class="btn btn-light" href="/expenses/index.php">Cancel</a><?php endif;?></div></form></div></div><div class="card p-3 mb-4"><form class="row g-2"><div class="col-md-3"><input class="form-control" name="search" placeholder="Search description" value="<?=e($search)?>"></div><div class="col-md-3"><select class="form-select" name="category_id"><option value="">All categories</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=$catFilter===$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></div><div class="col-md-2"><input class="form-control" name="from" type="date" value="<?=e($from)?>"></div><div class="col-md-2"><input class="form-control" name="to" type="date" value="<?=e($to)?>"></div><div class="col-md-2"><button class="btn btn-outline-secondary w-100">Filter</button></div></form></div><div class="card p-3 table-responsive"><table class="table align-middle"><thead><tr><th>Date</th><th>Category</th><th>Description</th><th>Amount</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['expense_date'])?></td><td><span class="badge text-bg-light"><?=e($r['category_name'])?></span></td><td><?=e($r['description'])?></td><td class="text-danger fw-bold"><?=currency($r['amount'])?></td><td class="text-end"><a class="btn btn-sm btn-outline-primary" href="?edit=<?=$r['id']?>">Edit</a><form method="post" class="d-inline"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button data-confirm="Delete this expense?" class="btn btn-sm btn-outline-danger">Delete</button></form></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5" class="text-center text-secondary py-4">No expenses found.</td></tr><?php endif;?></tbody></table></div><?php require_once __DIR__ . '/../includes/footer.php'; ?>
